import argparse
import json
import sys
from pathlib import Path
import cantools

def toDbc(input, output):
    # 1. Load the JSON structure generated by your script
    with input.open('r', encoding='utf-8') as f:
        jsonData = json.load(f)

    db = cantools.database.can.Database()

    messages = jsonData.get("messages", [])
    if not messages:
        raise ValueError("No 'messages' key or data found in the provided JSON file.")

    for msgInput in messages:
        try:
            frame_id = int(msgInput["id"], 16)
            
            signals = []
            for sigInput in msgInput.get("signals", []):
                endianness = sigInput["endian"].lower()
                byte_order = "big_endian" if "big" in endianness or "mot" in endianness else "little_endian"
                
                signal = cantools.database.can.Signal(
                    name=sigInput["name"],
                    start=sigInput["start_bit"],
                    length=sigInput["length"],
                    byte_order=byte_order,
                    is_signed=False  
                )
                signals.append(signal)
                
            message = cantools.database.can.Message(
                frame_id=frame_id,
                name=msgInput["name"],
                length=msgInput["size_bytes"],
                signals=signals,
                cycle_time=msgInput.get("period_ms")
            )
            db.messages.append(message)

        except (ValueError, KeyError) as error:
            raise ValueError(f"Error parsing message {msgInput.get('name', 'Unknown')}: {error!r}") from error

    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(db.as_dbc_string(), encoding="utf-8")


def main():
    parser = argparse.ArgumentParser(description="Convert your custom JSON CAN format to a Vector DBC file.")
    parser.add_argument("input_json", type=Path, help="Path to the JSON file generated by your script")
    parser.add_argument("output_dbc", type=Path, nargs="?", help="default: same name as input, .dbc")
    args = parser.parse_args()

    output = args.output_dbc or args.input_json.with_suffix(".dbc")
    try:
        toDbc(args.input_json, output)
    except (OSError, ValueError) as error:
        sys.exit(f"error: {error}")
    print(f"Successfully Converted {args.input_json} -> {output}")

if __name__ == "__main__":
    main()
